"""Specification for the beginner project. Do not edit this file."""

import numpy as np
import pandas as pd
import pytest

from clean_features import (
    apply_fill_values,
    clean_features,
    encode_categoricals,
    learn_fill_values,
)

NUMERIC = ["age", "income"]
CATEGORICAL = ["city"]


@pytest.fixture
def train_df():
    return pd.DataFrame(
        {
            "age": [25, 30, np.nan, 40, 200],  # 200 is an outlier
            "income": [30.0, 40.0, 50.0, np.nan, 60.0],
            "city": ["Delhi", "Mumbai", "Delhi", None, "Delhi"],
            "label": [0, 1, 0, 1, 0],
        }
    )


@pytest.fixture
def test_df():
    return pd.DataFrame(
        {
            "age": [np.nan, 28.0],
            "income": [45.0, np.nan],
            "city": ["Chennai", "Mumbai"],  # Chennai never appears in train
            "label": [1, 0],
        }
    )


def _filled(train_df):
    return apply_fill_values(train_df, learn_fill_values(train_df, NUMERIC, CATEGORICAL))


# ---------- learn_fill_values ----------

def test_numeric_fill_uses_median(train_df):
    fv = learn_fill_values(train_df, NUMERIC, CATEGORICAL)
    assert fv["age"] == 35.0  # median of 25, 30, 40, 200
    assert fv["income"] == 45.0


def test_categorical_fill_uses_most_frequent(train_df):
    fv = learn_fill_values(train_df, NUMERIC, CATEGORICAL)
    assert fv["city"] == "Delhi"


def test_all_missing_column_raises_value_error():
    df = pd.DataFrame({"age": [np.nan, np.nan], "city": ["a", "b"]})
    with pytest.raises(ValueError):
        learn_fill_values(df, ["age"], ["city"])


# ---------- apply_fill_values ----------

def test_apply_fill_leaves_no_missing(train_df):
    out = _filled(train_df)
    assert out[NUMERIC + CATEGORICAL].isna().sum().sum() == 0


def test_apply_fill_does_not_modify_input(train_df):
    before = train_df.copy(deep=True)
    _ = _filled(train_df)
    pd.testing.assert_frame_equal(train_df, before)


def test_apply_fill_keeps_other_columns(train_df):
    out = _filled(train_df)
    assert out["label"].tolist() == train_df["label"].tolist()


# ---------- encode_categoricals ----------

def test_encoding_learns_sorted_categories(train_df):
    _, cats = encode_categoricals(_filled(train_df), CATEGORICAL)
    assert cats == {"city": ["Delhi", "Mumbai"]}


def test_encoding_removes_original_and_adds_dummies(train_df):
    out, _ = encode_categoricals(_filled(train_df), CATEGORICAL)
    assert "city" not in out.columns
    assert "city_Delhi" in out.columns and "city_Mumbai" in out.columns


def test_encoding_output_is_integer_zero_one(train_df):
    out, _ = encode_categoricals(_filled(train_df), CATEGORICAL)
    for col in ["city_Delhi", "city_Mumbai"]:
        assert pd.api.types.is_integer_dtype(out[col])
        assert set(out[col].unique()) <= {0, 1}


def test_encoding_with_given_categories_is_stable(test_df):
    cats = {"city": ["Delhi", "Mumbai"]}
    out, used = encode_categoricals(test_df, CATEGORICAL, cats)
    assert used == cats
    assert [c for c in out.columns if c.startswith("city_")] == ["city_Delhi", "city_Mumbai"]


def test_unseen_category_becomes_all_zeros(test_df):
    cats = {"city": ["Delhi", "Mumbai"]}
    out, _ = encode_categoricals(test_df, CATEGORICAL, cats)
    chennai_row = out.iloc[0]  # city == "Chennai"
    assert chennai_row["city_Delhi"] == 0
    assert chennai_row["city_Mumbai"] == 0


def test_encoding_does_not_modify_input(train_df):
    filled = _filled(train_df)
    before = filled.copy(deep=True)
    _ = encode_categoricals(filled, CATEGORICAL)
    pd.testing.assert_frame_equal(filled, before)


# ---------- clean_features (end to end) ----------

def test_train_and_test_have_identical_columns(train_df, test_df):
    tr, te = clean_features(train_df, test_df, NUMERIC, CATEGORICAL)
    assert list(tr.columns) == list(te.columns)


def test_columns_are_in_fixed_order(train_df, test_df):
    tr, _ = clean_features(train_df, test_df, NUMERIC, CATEGORICAL)
    assert list(tr.columns) == ["age", "income", "label", "city_Delhi", "city_Mumbai"]


def test_no_missing_values_after_cleaning(train_df, test_df):
    tr, te = clean_features(train_df, test_df, NUMERIC, CATEGORICAL)
    assert tr.isna().sum().sum() == 0
    assert te.isna().sum().sum() == 0


def test_test_data_cannot_influence_train_output(train_df, test_df):
    tr_a, _ = clean_features(train_df, test_df, NUMERIC, CATEGORICAL)

    shifted = test_df.copy()
    shifted["age"] = [9999.0, 9999.0]
    shifted["income"] = [9999.0, 9999.0]
    tr_b, _ = clean_features(train_df, shifted, NUMERIC, CATEGORICAL)

    pd.testing.assert_frame_equal(tr_a, tr_b)


def test_test_set_is_filled_with_train_statistics(train_df, test_df):
    _, te = clean_features(train_df, test_df, NUMERIC, CATEGORICAL)
    assert te.loc[0, "age"] == 35.0      # train median
    assert te.loc[1, "income"] == 45.0   # train median


def test_clean_features_does_not_modify_inputs(train_df, test_df):
    tr_before, te_before = train_df.copy(deep=True), test_df.copy(deep=True)
    _ = clean_features(train_df, test_df, NUMERIC, CATEGORICAL)
    pd.testing.assert_frame_equal(train_df, tr_before)
    pd.testing.assert_frame_equal(test_df, te_before)
